typedef unsigned int u_int;

class nglTexStreamPos
{
public:
  u_int addr, cycle;
};

struct nglVif1IntEntry;

extern int nglNVif1IntEntries;
extern nglVif1IntEntry* nglVif1IntCurTexEntry;
extern u_int nglDisplayWidth;
extern u_int nglDisplayHeight;
extern u_int nglLockBufferSize;
extern nglTexStreamPos nglTexStreamPrevStartRef;
extern nglTexStreamPos nglTexStreamCurStartRef;
extern nglTexStreamPos nglTexStreamAlloc;
extern u_int* nglLastIntAddr;

void nglFatal( const char* Format, ... );
void nglVif1IntCreateTextureBlock();

__asm__(".equ nglNVif1IntEntries,0x004BB780");
__asm__(".equ nglVif1IntCurTexEntry,0x004BB790");
__asm__(".equ nglDisplayWidth,0x004BB820");
__asm__(".equ nglDisplayHeight,0x004BB824");
__asm__(".equ nglLockBufferSize,0x004BBD0C");
__asm__(".equ nglTexStreamPrevStartRef,0x004BBD10");
__asm__(".equ nglTexStreamCurStartRef,0x004BBD18");
__asm__(".equ nglTexStreamAlloc,0x004BBD20");
__asm__(".equ nglLastIntAddr,0x004BC064");
__asm__(".equ nglFatal__FPCce,0x003AC0C0");
__asm__(".equ nglVif1IntCreateTextureBlock__Fv,0x0039F660");

#define NGL_FRAME_PIXELSIZE 4
#define NGL_VRAM_FRAME_SIZE ( ( nglDisplayWidth * nglDisplayHeight * NGL_FRAME_PIXELSIZE ) / 256 )
#define NGL_VRAM_LOCKED_START ( NGL_VRAM_FRAME_SIZE * 3 )
#define NGL_VRAM_LOCKED_END ( NGL_VRAM_LOCKED_START + nglLockBufferSize )
#define NGL_VRAM_STREAM_START NGL_VRAM_LOCKED_END
#define SCE_VIF1_SET_NOP(irq) ((u_int)(irq) << 31)
#define SCE_VIF1_SET_FLUSHA(irq) (((u_int)(irq) << 31) | 0x13000000)

void nglVif1AddTextureStreamSetup( u_int*& Packet )
{
  nglNVif1IntEntries = 0;
  nglVif1IntCurTexEntry = 0;

  nglTexStreamAlloc.addr = NGL_VRAM_STREAM_START;
  nglTexStreamAlloc.cycle += 2;
  if (nglTexStreamAlloc.cycle >= 0xFFFF0000)
    nglFatal( "nglTexStreamAlloc.cycle got too close to wrapping (%d).\n", nglTexStreamAlloc.cycle );

  nglTexStreamPrevStartRef = nglTexStreamAlloc;
  nglTexStreamCurStartRef = nglTexStreamAlloc;

  nglLastIntAddr = 0;
  *(Packet++) = SCE_VIF1_SET_NOP( 1 );
  *(Packet++) = SCE_VIF1_SET_FLUSHA( 0 );
  nglLastIntAddr = Packet;
  *(Packet++) = SCE_VIF1_SET_NOP( 1 );

  nglVif1IntCreateTextureBlock();
}
